import{_ as e,o as t,c as l,a2 as i}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"1.2 做出完整体验原型","description":"用可点击原型走通任务、审批、产物和恢复。","frontmatter":{"title":"1.2 做出完整体验原型","description":"用可点击原型走通任务、审批、产物和恢复。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-1/1-2.md","filePath":"delivery/stage-1/1-2.md","lastUpdated":1794017073000}'),r={name:"delivery/stage-1/1-2.md"};function o(n,a,s,d,_,c){return t(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="_1-2-做出完整体验原型" tabindex="-1">1.2 做出完整体验原型 <a class="header-anchor" href="#_1-2-做出完整体验原型" aria-label="Permalink to &quot;1.2 做出完整体验原型&quot;">​</a></h1><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><ul><li><strong>已完成：</strong> 用实际 Web 控制面走通了任务卡、审批、产物和失败恢复，覆盖排队、执行、等待审批、完成、失败与恢复等关键状态。</li><li><strong>边界：</strong> 原型没有伪造成功状态；未知、失败和无法完成都如实显示。</li></ul><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>做出一个覆盖完整使用路径的可点击原型，让用户在真正开发前就能看懂产品如何工作。原型必须包含任务卡、审批、产物和失败恢复，而不是只有首页。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>设计四个主要入口：今日任务、需要你、产物、设置。</li><li>覆盖任务从创建到结束的所有关键状态：排队、执行中、等待补充信息、等待审批、已完成、失败、可恢复、已取消。</li><li>每个状态只保留一个主操作，并明确告诉用户下一步是什么。</li><li>把任务卡、审批页、产物页和失败说明做成可以点击的完整流程。</li><li>用假数据演示，但不要伪造成功；未知、失败和无法完成都要如实显示。</li><li>请首位用户在电脑和手机上各走一遍，记录卡住和看不懂的地方并修正。</li></ol>',7)])])}const p=e(r,[["render",o]]);export{u as __pageData,p as default};
